def gen(rng):
    def fmt(pts, p):
        return '%d %d\n%s' % (len(pts), p, '\n'.join('%d %d' % q for q in pts))
    tests = [fmt([(0, 0)], 4), fmt([(3, 3), (3, 3), (3, 3)], 4), fmt([(0, 0), (5, 5)], 4),
             fmt([(0, 0), (1, 1)], 4), fmt([(0, 0), (2, 0), (0, 2), (2, 2)], 8),
             fmt([(0, 0), (4, 0), (0, 4), (4, 4)], 8), fmt([(0, 0), (4, 0), (0, 4), (4, 4)], 16),
             fmt([(0, 0), (1, 0), (2, 0), (3, 0), (4, 0)], 6), fmt([(-2, 5), (-2, 3), (0, 4)], 6)]
    for n in (2, 3, 4, 5, 6, 8, 10):
        for _ in range(4):
            c = rng.choice([4, 6, 9])
            pts = [(rng.randint(0, c), rng.randint(0, c)) for _ in range(n)]
            tests.append(fmt(pts, 2 * rng.randint(2, 7)))
    N = 150
    for c, p in ((60, 120), (150, 200), (300, 300), (10, 40)):
        tests.append(fmt([(rng.randint(0, c), rng.randint(0, c)) for _ in range(N)], p))
    B = 10**9
    tests.append(fmt([(rng.randint(-B, B), rng.randint(-B, B)) for _ in range(N)], 300))
    tests.append(fmt([(i, (i * 7) % 101) for i in range(N)], 300))
    tests.append(fmt([(i % 100, i // 100 * 150) for i in range(N)], 300))
    return tests

